package com.marketlabs.pulse.utils.extensions

// Generated by Claude Code.

import java.util.Locale

/**
 * Minor words that stay lowercase in [smartTitleCase] unless they open or close the headline --
 * articles, coordinating conjunctions, and the short (<=3-letter) prepositions. Longer prepositions
 * ("amid", "into", "from", "with", "over", ...) are deliberately NOT in this list -- standard title
 * case capitalizes those, only the short function words stay lowercase.
 */
private val MINOR_WORDS = setOf(
    "a", "an", "and", "as", "at", "but", "by", "for", "in",
    "nor", "of", "on", "or", "per", "so", "the", "to", "up", "via", "yet"
)

/**
 * Normalizes an AI-generated headline to Title Case. The backend sends these two ways
 * inconsistently -- sometimes already proper Title Case ("Resilient Economic Foundations Anchor a
 * Consolidating Market Amid Broad Valuation Headwinds"), sometimes plain sentence case ("Amazon
 * falls 2% amid DOJ probe") -- this normalizes either input to the same Title Case output, with
 * minor words (see [MINOR_WORDS]) lowercase except at the very start or end of the headline.
 *
 * Only meant for the AI-synthesis/Digest headline fields that actually arrive this
 * inconsistently -- the Indicators executive-synthesis headline ("Today's Read") and the
 * Digest/synthesis headlines (Stock Detail's Digest, Insights' Posture/Positioning/Risks/
 * Playbook via `SynthesisHeroCard`). Not applied to news headlines, Market Signal, or Market
 * Sentiment -- those already read fine as sentence case and don't share this inconsistency.
 *
 * A word that's already all-uppercase and more than one letter (an acronym like "DOJ", "GDP",
 * "S&P") is left exactly as-is rather than run through the lowercase-then-capitalize-first pass
 * every other word gets -- title-casing an acronym letter-by-letter would silently destroy it
 * ("DOJ" -> "Doj"). Hyphenated words are title-cased per segment ("beef-pricing" ->
 * "Beef-Pricing").
 */
fun String.smartTitleCase(): String {
    val words = trim().split(Regex("\\s+")).filter { it.isNotEmpty() }
    if (words.isEmpty()) return this

    return words.mapIndexed { index, word ->
        val isEdgeWord = index == 0 || index == words.lastIndex
        val forceCapitalize = isEdgeWord || word.lowercase(Locale.US) !in MINOR_WORDS
        titleCaseWord(word, forceCapitalize)
    }.joinToString(" ")
}

private fun titleCaseWord(word: String, forceCapitalize: Boolean): String {
    if (word.isEmpty()) return word

    return word.split("-").joinToString("-") { segment ->
        when {
            isAcronym(segment) -> segment
            forceCapitalize -> segment.lowercase(Locale.US).replaceFirstChar { it.titlecase(Locale.US) }
            else -> segment.lowercase(Locale.US)
        }
    }
}

private fun isAcronym(segment: String): Boolean {
    val letters = segment.filter { it.isLetter() }
    return letters.length > 1 && letters.all { it.isUpperCase() }
}
